{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "MP-10, the closest analogue (Morgan 0.4286), produced significant, homogeneously distributed striatal and cortical FDG uptake in monkey PET after IV administration, directly demonstrating CNS access and central target engagement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "[11C]MP-10 PET in pig and baboon showed specific, discrete, reversible striatal uptake, confirming BBB penetration in two non-rodent species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "[11C]MP-10 rapidly entered pig brain, reaching peak striatal concentrations 1-2 min after injection, indicating fast and substantial brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A close analogue with the same pyrazolyl-pyridyl-phenoxymethyl core showed striatal brain uptake in rat biodistribution, supporting transfer of the CNS-penetrant phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "MW150, a related pyrazole-pyridyl compound, showed a rat brain/plasma ratio >0.9 at 3 h, confirming robust BBB distribution in a direct tissue-penetrance screen.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A methylpyridine-containing pyridazinone analogue showed low brain-to-plasma ratio, but its low similarity (0.25) and different scaffold limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The query is a close structural analogue of MP-10, which has repeatedly demonstrated robust BBB penetration and central target engagement by PET in monkeys, pigs, baboons, and rodents. Multiple related pyrazole-pyridyl compounds also show brain uptake in rats, mice, and humans. The single negative methylpyridine analogue is structurally distant and outweighed by direct positive evidence.",
  "evidence_gaps": [
    "No direct experimental brain/plasma or PET measurement for the exact query molecule.",
    "Efflux transporter status (P-gp/BCRP) of the query not directly measured.",
    "Free brain concentration and target occupancy not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

